/**
 * Tests for the docs-freshness guard's coverage of `.env.example`.
 *
 * `.env.example` is generated by `scripts/generate-env-example.ts`, and for a
 * long time it was neither produced by `pnpm docs:all` nor diffed by
 * `check:docs`. CONTRIBUTING.md documented the manual step; nothing enforced
 * it. So adding an env var and running the documented regen command left the
 * file stale while every check reported green — a check that could not fail.
 *
 * That is worse here than for a normal generated artifact: `.env.example` is
 * the file an operator copies to create `.env`, so a variable missing from it
 * ships as an unset default nobody was told about. `SESSION_COOKIE_SECURE`
 * was caught by hand; the next one would not be.
 *
 * Both halves are pinned, because each covers a case the other misses:
 *   - `docs:all` generating it closes the gap locally, which matters while CI
 *     is unavailable.
 *   - `check:docs` diffing it also catches a hand-edit, which regeneration
 *     alone never would.
 *
 * Run: `pnpm exec tsx --test scripts/check-docs-fresh.test.ts`.
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const REPO_ROOT = join(import.meta.dirname, '..')

function read(rel: string): string {
  return readFileSync(join(REPO_ROOT, rel), 'utf8')
}

test('docs:all generates .env.example', () => {
  const pkg = JSON.parse(read('package.json')) as { scripts: Record<string, string> }
  const chain = pkg.scripts['docs:all']
  assert.ok(chain, 'package.json has no docs:all script')
  assert.match(
    chain,
    /generate:env-example/,
    'docs:all must run generate:env-example — otherwise the documented regen command leaves .env.example stale',
  )
})

test('generate:env-example is a real script, not just a name in the chain', () => {
  const pkg = JSON.parse(read('package.json')) as { scripts: Record<string, string> }
  assert.ok(
    pkg.scripts['generate:env-example'],
    'docs:all references generate:env-example but no such script is defined',
  )
})

test('check:docs diffs .env.example', () => {
  const guard = read('scripts/check-docs-fresh.ts')
  // The path must be inside the generatedPaths array that feeds `git diff`,
  // not merely mentioned in a comment.
  const arrayBlock = /const generatedPaths = \[([\s\S]*?)\n  \]/.exec(guard)
  assert.ok(arrayBlock, 'could not locate the generatedPaths array in check-docs-fresh.ts')
  assert.match(
    arrayBlock[1]!,
    /['"]\.env\.example['"]/,
    'check:docs must diff .env.example, so a hand-edit or a skipped regen fails the gate',
  )
})

test('CONTRIBUTING no longer tells contributors to regenerate .env.example by hand', () => {
  // The caveat was accurate while the exclusion existed. Leaving it in place
  // after closing the gap would send contributors to run a step docs:all now
  // performs, and imply the guard still does not cover it.
  const contributing = read('CONTRIBUTING.md')
  assert.doesNotMatch(
    contributing,
    /is \*not\* in this chain; regenerate it with `pnpm generate:env-example`/,
    'CONTRIBUTING.md still documents the manual step that docs:all now covers',
  )
})

test('.env.example carries the variable that exposed the gap', () => {
  // Regression anchor for the specific miss: SESSION_COOKIE_SECURE reached
  // the env-var table via docs:all but not this file, because only one of the
  // two generators ran.
  const example = read('.env.example')
  assert.match(
    example,
    /^SESSION_COOKIE_SECURE=/m,
    '.env.example is missing SESSION_COOKIE_SECURE — regenerate with pnpm docs:all',
  )
})
